package com.bank.ledger.service;

import com.bank.ledger.dto.LedgerResult;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.util.*;
import java.util.stream.*;

@Service
@Slf4j
public class LedgerService {

    // ═══ DEMO 1: sorted() blocks fusion — proof with logging ═══
    public LedgerResult demonstrateFusionBlock() {
        List<String> executionLog = new ArrayList<>();

        List.of("HDFC", "RELIANCE", "TCS", "INFY", "WIPRO").stream()
            .peek(s -> executionLog.add("[BEFORE-SORT] " + s))
            .sorted()
            .peek(s -> executionLog.add("[AFTER-SORT] " + s))
            .map(String::toLowerCase)
            .peek(s -> executionLog.add("[AFTER-MAP] " + s))
            .toList();

        // Log proves: ALL before-sort FIRST, then after-sort in sorted order
        return new LedgerResult("FUSION_BLOCKED_BY_SORTED",
            5, 0, executionLog,
            "sorted() consumes ALL upstream elements before emitting. " +
            "Before-sort: HDFC,RELIANCE,TCS,INFY,WIPRO (source order). " +
            "After-sort: HDFC,INFY,RELIANCE,TCS,WIPRO (sorted). Fusion blocked at sorted().");
    }

    // ═══ DEMO 2: filter BEFORE sort vs AFTER sort — performance ═══
    public LedgerResult demonstrateOrderingOptimization() {
        int size = 100_000;
        List<Integer> data = new Random(42).ints(size, 0, 1000).boxed().collect(Collectors.toList());

        // BAD: sort ALL, then filter
        long start1 = System.nanoTime();
        List<Integer> bad = data.stream()
            .sorted()                                   // sorts ALL 100K
            .filter(n -> n > 800)                       // keeps ~20K
            .toList();
        long dur1 = System.nanoTime() - start1;

        // GOOD: filter FIRST, then sort
        long start2 = System.nanoTime();
        List<Integer> good = data.stream()
            .filter(n -> n > 800)                       // reduces to ~20K
            .sorted()                                   // sorts only ~20K
            .toList();
        long dur2 = System.nanoTime() - start2;

        return new LedgerResult("FILTER_BEFORE_SORT_OPTIMIZATION",
            size, dur2,
            List.of("sort-then-filter: " + dur1/1000 + "μs (sorted " + size + " elements)",
                     "filter-then-sort: " + dur2/1000 + "μs (sorted " + good.size() + " elements)",
                     "Speedup: " + (dur1 / Math.max(dur2, 1)) + "x"),
            "Filter BEFORE sort reduces elements to sort. " +
            "Sorted " + good.size() + " instead of " + size + ".");
    }

    // ═══ DEMO 3: stateful vs stateless memory ═══
    public LedgerResult demonstrateStatefulMemory() {
        List<String> log = new ArrayList<>();

        // STATELESS: filter + map — O(1) memory, one element at a time
        log.add("STATELESS (filter+map): O(1) memory — processes one element, forgets, moves to next");

        // STATEFUL: sorted — O(n) memory, buffers ALL elements
        log.add("STATEFUL (sorted): O(n) memory — buffers entire stream before emitting");

        // STATEFUL: distinct — O(n) memory, HashSet of seen elements
        log.add("STATEFUL (distinct): O(n) memory — maintains HashSet of all seen elements");

        // STATEFUL: limit/skip — O(1) memory, but counter
        log.add("STATEFUL (limit/skip): O(1) memory — just a counter, but ordering-aware in parallel");

        return new LedgerResult("STATEFUL_VS_STATELESS",
            0, 0, log,
            "Stateful ops: sorted (buffer all), distinct (HashSet), limit/skip (counter). " +
            "Stateless ops: filter, map, flatMap, peek (one element at a time).");
    }
}
