// ─── File: src/test/java/com/bank/ledger/service/SortedStatefulTest.java ───
package com.bank.ledger.service;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.stream.Stream;
import static org.assertj.core.api.Assertions.*;

class SortedStatefulTest {

    @Test
    void sortedBuffersAllBeforeEmitting() {
        List<String> log = new ArrayList<>();

        List.of("C", "A", "B").stream()
            .peek(s -> log.add("before:" + s))
            .sorted()
            .peek(s -> log.add("after:" + s))
            .toList();

        // All "before" entries come FIRST (sorted consumed all), then "after" in sorted order
        assertThat(log.subList(0, 3)).containsExactly("before:C", "before:A", "before:B");
        assertThat(log.subList(3, 6)).containsExactly("after:A", "after:B", "after:C");
    }

    @Test
    void filterBeforeSortReducesWork() {
        List<String> sortLog = new ArrayList<>();

        List.of(5, 3, 8, 1, 9, 2, 7).stream()
            .filter(n -> n > 5)                    // reduces to [8, 9, 7]
            .peek(n -> sortLog.add("to-sort:" + n))
            .sorted()
            .toList();

        // Only 3 elements reached sorted() — not all 7
        assertThat(sortLog).hasSize(3);
        assertThat(sortLog).containsExactly("to-sort:8", "to-sort:9", "to-sort:7");
    }

    @Test
    void sortedWithComparator() {
        List<String> result = Stream.of("TCS", "RELIANCE", "HDFC")
            .sorted(Comparator.comparingInt(String::length).reversed())
            .toList();
        assertThat(result).containsExactly("RELIANCE", "HDFC", "TCS");
    }

    @Test
    void distinctIsAlsoStateful() {
        List<String> log = new ArrayList<>();

        Stream.of("A", "B", "A", "C", "B").stream()
            .peek(s -> log.add("in:" + s))
            .distinct()
            .peek(s -> log.add("out:" + s))
            .toList();

        // distinct passes first occurrence immediately, drops duplicates
        // But maintains internal HashSet — O(n) memory
        assertThat(log).contains("in:A", "out:A", "in:B", "out:B", "in:A", "in:C", "out:C");
    }
}
